        smallButton(form, "Bez terminu", () -> date.setText(""));

        TextView label = text("Powtarzanie", 15, true);
        form.addView(label);
        Spinner repeat = new Spinner(this);
        repeat.setAdapter(themeSpinnerAdapter(java.util.Arrays.asList(TaskRules.LABELS)));
