    private void showStatementEntries(
            java.util.List<BankStatementCsv.Entry> rows, String bank) {
        showFilteredStatementEntries(rows,bank,0);
    }

    private void showStatementFilters(
            java.util.List<BankStatementCsv.Entry> rows,String bank) {
        final String[] filters={"Wszystkie","1 propozycja","Kilka propozycji",
            "Bez pasującego wpisu","Wydatki −","Wpływy +"};
        new AlertDialog.Builder(this).setTitle("Filtruj potwierdzenia")
            .setItems(filters,(d,filter)->
                showFilteredStatementEntries(rows,bank,filter))
            .setNegativeButton("Zamknij",null).show();
    }

    private void showFilteredStatementEntries(
            java.util.List<BankStatementCsv.Entry> rows,String bank,int filter) {
        java.util.List<BankStatementCsv.Entry> visible=new java.util.ArrayList<>();
        java.util.List<String> labels=new java.util.ArrayList<>();
        int duplicates=0;
        SQLiteDatabase read=db.getReadableDatabase();
        for(BankStatementCsv.Entry entry:rows) {
            boolean used;
            try(Cursor c=read.rawQuery(
                    "SELECT 1 FROM paycheck_transactions WHERE statement_key=?",
                    new String[]{entry.evidenceKey})) {
                used=c.moveToFirst();
            }
            if(used){duplicates++;continue;}
            int pending=0;
            try(Cursor c=read.rawQuery(
                    "SELECT COUNT(*) FROM paycheck_transactions "
                    +"WHERE scope='shared' AND status='pending' "
                    +"AND kind=? AND amount_grosz=?",
                    new String[]{entry.kind,Long.toString(entry.amountGrosz)})) {
                if(c.moveToFirst())pending=c.getInt(0);
            }
            if(filter==1&&pending!=1 || filter==2&&pending<2
                    || filter==3&&pending!=0
                    || filter==4&&!"expense".equals(entry.kind)
                    || filter==5&&!"income".equals(entry.kind))
                continue;
            visible.add(entry);
            String description=entry.description.length()>55
                ?entry.description.substring(0,55)+"…" : entry.description;
            labels.add(entry.date+" • "
                +("income".equals(entry.kind)?"+ ":"− ")
                +MoneyRules.format(entry.amountGrosz)+"\n"
                +description+"\n"
                +(pending==1?"✓ 1 propozycja • sprawdź i zatwierdź"
                    :pending>1?"? "+pending+" możliwych wpisów • wybierz"
                    :"— Brak oczekującego wpisu"));
        }
        if(visible.isEmpty()&&filter==0&&duplicates==rows.size()){
            alert("Wszystkie pozycje już uzgodnione. "
                +"Nie odjęto ponownie pieniędzy.");render();return;
        }
        new AlertDialog.Builder(this)
            .setTitle("Potwierdzenia • "+bank+" • "+visible.size())
            .setMessage("Zduplikowane: "+duplicates+". "
                +"Dopasowania to propozycje, nie automatyczne księgowanie. "
                +"Saldo zmienia się wyłącznie po Twoim zatwierdzeniu.")
            .setItems(labels.toArray(new String[0]),(d,index)->
                matchStatementEntry(visible.get(index),rows,bank))
            .setNeutralButton("Filtry",(d,w)->showStatementFilters(rows,bank))
            .setNegativeButton("Zamknij",null).show();
    }

    private void matchStatementEntry(BankStatementCsv.Entry statement,
            java.util.List<BankStatementCsv.Entry> rows,String bank){
        java.util.List<String> ids=new java.util.ArrayList<>();
        java.util.List<String> labels=new java.util.ArrayList<>();
        try(Cursor c=db.getReadableDatabase().rawQuery(
                "SELECT operation_id,note,created_at FROM paycheck_transactions "
                + "WHERE scope='shared' AND status='pending' AND kind=? "
                + "AND amount_grosz=? ORDER BY id DESC LIMIT 40",
                new String[]{statement.kind,
                    Long.toString(statement.amountGrosz)})){
            while(c.moveToNext()){
                ids.add(c.getString(0));
                String note=c.getString(1);
                labels.add((note.isEmpty()?"Bez opisu":note)
                    +" • "+Instant.ofEpochMilli(c.getLong(2))
                        .atZone(ZoneId.systemDefault()).toLocalDate());
            }
        }
        if(ids.isEmpty()){
            alert("Brak oczekującej transakcji o tym samym znaku i kwocie. "
                + "Import NIE tworzy nowej płatności.");return;
        }
        if(ids.size()==1) {
            confirmStatementMatch(statement,rows,bank,ids.get(0),labels.get(0));
            return;
        }
        new AlertDialog.Builder(this).setTitle("Wybierz właściwą transakcję")
            .setMessage(statement.date+" • "
                +("income".equals(statement.kind)?"+ ":"− ")
                +MoneyRules.format(statement.amountGrosz)
                +"\n"+statement.description
                +"\nKilka identycznych kwot. Nie wybieram za Ciebie.")
            .setItems(labels.toArray(new String[0]),(d,index)->
                confirmStatementMatch(statement,rows,bank,
                    ids.get(index),labels.get(index)))
            .setNegativeButton("Powrót",null).show();
    }

    private void confirmStatementMatch(BankStatementCsv.Entry statement,
            java.util.List<BankStatementCsv.Entry> rows,String bank,
            String operationId,String candidateLabel) {
        new AlertDialog.Builder(this).setTitle("Potwierdź dopasowanie")
            .setMessage(statement.date+" • "
                +("income".equals(statement.kind)?"+ ":"− ")
                +MoneyRules.format(statement.amountGrosz)
                +"\n"+statement.description+"\n\n"
                +"Wpis PayCheck: "+candidateLabel+"\n\n"
                +"To propozycja z importowanego pliku, nie "
                +"uwierzytelnione połączenie z bankiem. "
                +"Saldo zmieni się tylko raz po zatwierdzeniu.")
            .setNegativeButton("Anuluj",null)
            .setPositiveButton("Zatwierdź parę",(dialog,which)->{
                try {
                    String outcome=PaycheckStore.matchStatement(
                        db.getWritableDatabase(),operationId,
                        statement.kind,statement.amountGrosz,
                        statement.evidenceKey,statement.date);
                    if("MATCHED".equals(outcome)){
                        DiagnosticLog.event("PAYCHECK_CSV_MATCHED");
                        Runnable done=()->{
                            render();
                            showStatementEntries(rows,bank);
                        };
                        if(!offerSharedBudgetMatch(operationId,done))
                            done.run();
                    }else if("ALREADY_MATCHED".equals(outcome))
                        alert("Ten wpis jest już uzgodniony.");
                    else alert("Nie uzgodniono: ta transakcja "
                        +"lub identyfikator CSV były już użyte.");
                }catch(Exception error){
                    DiagnosticLog.event("PAYCHECK_CSV_MATCH_FAILED");
                    alert("Nie zapisano uzgodnienia. Saldo bez zmian.");
                }
            }).show();
    }

    /** A manual attestation, NOT an automated bank statement verification. */
    private void confirmSharedPaycheckEntry(String operationId) {
        confirmSharedPaycheckEntry(operationId,null);
    }

    private void confirmSharedPaycheckEntry(String operationId,String hintKey) {
        new AlertDialog.Builder(this)
            .setTitle("Potwierdź operację?")
            .setMessage("Potwierdź wyłącznie po sprawdzeniu faktycznej transakcji "
                + "w banku lub na wyciągu. Powiadomienie bankowe nie jest "
                + "dowodem zaksięgowania. Zatwierdzenie zmieni saldo tylko raz.")
            .setNegativeButton("Anuluj", null)
            .setPositiveButton("Sprawdziłem — potwierdź", (d,w) -> {
                try {
                    String result=PaycheckStore.confirm(db.getWritableDatabase(),
                        operationId);
                    if ("CONFIRMED".equals(result)) {
                        if(hintKey!=null)BankNotificationHints.remove(this,hintKey);
                        DiagnosticLog.event("PAYCHECK_SHARED_CONFIRMED");
                        if(!offerSharedBudgetMatch(operationId,this::render))
                            render();
                    } else {
                        alert("Operacja już potwierdzona lub nie istnieje.");
                        render();
                    }
                } catch (Exception error) {
                    DiagnosticLog.error("PAYCHECK_CONFIRM", error);
                    alert("Nie udało się potwierdzić. Saldo pozostało bez zmian.");
                }
            }).show();
    }

    private boolean offerSharedBudgetMatch(String operationId,
            Runnable done) {
        try (Cursor tx = db.getReadableDatabase().rawQuery(
                "SELECT kind,category,amount_grosz,created_at,statement_date,status "
                + "FROM paycheck_transactions "
                + "WHERE scope='shared' AND operation_id=?",
                new String[]{operationId})) {
            if (!tx.moveToFirst() || !"confirmed".equals(tx.getString(5)))
                return false;

            final String kind = tx.getString(0);
            final String category = tx.getString(1);
            final long txAmount = tx.getLong(2);
            final YearMonth month = PaycheckMonthlyBudget.transactionMonth(
                tx.getLong(3),tx.isNull(4)?null:tx.getString(4));
            final java.util.List<PaycheckMonthlyBudget.Item> items =
                PaycheckMonthlyBudget.load(prefs);

            final PaycheckMonthlyBudget.Item candidate =
                PaycheckMonthlyBudget.suggest(items,month,
                    kind,category,txAmount);
            final java.util.List<PaycheckMonthlyBudget.Item> split =
                budgetSplitItems(items,month,kind,txAmount);

            if (candidate == null && split == null) return false;

            java.util.List<String> choices = new java.util.ArrayList<>();
            java.util.List<Integer> actions = new java.util.ArrayList<>();
            if (candidate != null) {
                choices.add("Przypisz całość → " + budgetItemDisplayName(candidate)
                    + " • " + MoneyRules.format(
                        PaycheckMonthlyBudget.plannedAmount(candidate,month)));
                actions.add(1);
            }
            if (split != null) {
                StringBuilder names = new StringBuilder();
                long plannedSum = 0L;
                for (int i=0;i<split.size();i++) {
                    if (i>0) names.append(" + ");
                    if (i<3) names.append(budgetItemDisplayName(split.get(i)));
                    else if (i==3) names.append("… +")
                        .append(split.size()-3).append(" poz.");
                    plannedSum = Math.addExact(plannedSum,
                        PaycheckMonthlyBudget.plannedAmount(split.get(i),month));
                }
                choices.add("Podziel na " + split.size() + " pozycje → "
                    + names + " • plan " + MoneyRules.format(plannedSum));
                actions.add(2);
            }
            choices.add("Nie, zostaw poza planem");
            actions.add(0);

            new AlertDialog.Builder(this)
                .setTitle("Pasuje do Budżetu miesiąca")
                .setMessage(MoneyRules.format(txAmount)
                    + " • " + budgetMonthLabel(month)
                    + "\n\nMożesz przypisać całą płatność albo rozdzielić "
                    + "jeden przelew na kilka pasujących pozycji planu. "
                    + "Jeżeli suma różni się nieznacznie, różnica zostanie "
                    + "jawnie pokazana w rozliczeniu. Saldo nie zmieni się drugi raz.")
                .setItems(choices.toArray(new String[0]),(d,index)->{
                    int action=actions.get(index);
                    if(action==0) {
                        done.run();
                        return;
                    }
                    try {
                        if(action==1) {
                            PaycheckMonthlyBudget.match(
                                prefs,candidate.id,operationId);
                            DiagnosticLog.event(
                                "PAYCHECK_SHARED_BUDGET_MATCHED");
                        } else {
                            allocateBudgetSplit(
                                split,month,operationId,txAmount);
                            DiagnosticLog.event(
                                "PAYCHECK_SHARED_BUDGET_SPLIT_MATCHED",
                                "count="+split.size());
                        }
                    } catch(Exception error) {
                        DiagnosticLog.error(
                            "PAYCHECK_SHARED_BUDGET_MATCH",error);
                        alert("Transakcja została potwierdzona, ale nie "
                            + "przypisano jej do budżetu.");
                    }
                    done.run();
                })
                .setNegativeButton("Anuluj",(d,w)->done.run())
                .show();
            return true;
        } catch(Exception error) {
            DiagnosticLog.error("PAYCHECK_BUDGET_SUGGEST",error);
            return false;
        }
    }

    private java.util.List<PaycheckMonthlyBudget.Item> budgetSplitItems(
            java.util.List<PaycheckMonthlyBudget.Item> items,
            YearMonth month, String kind, long transactionAmount) {
        java.util.List<PaycheckMonthlyBudget.Item> candidates =
            new java.util.ArrayList<>();
        for (PaycheckMonthlyBudget.Item item
                : PaycheckMonthlyBudget.activeFor(items,month)) {
            if (!kind.equals(item.kind)) continue;
            long already = PaycheckMonthlyBudget.sharedMatchedActual(
                db.getReadableDatabase(),item,month);
            if (already > 0) continue;
            candidates.add(item);
        }
        if (candidates.size() < 2) return null;

        long tolerance = Math.max(100L,transactionAmount*2L/100L);
        long maxSum;
        try { maxSum = Math.addExact(transactionAmount,tolerance); }
        catch (ArithmeticException overflow) { maxSum = Long.MAX_VALUE; }

        java.util.Map<Long,java.util.List<PaycheckMonthlyBudget.Item>> sums =
            new java.util.HashMap<>();
        java.util.Set<Long> ambiguous = new java.util.HashSet<>();
        sums.put(0L,new java.util.ArrayList<>());

        for (PaycheckMonthlyBudget.Item item : candidates) {
            long amount = PaycheckMonthlyBudget.plannedAmount(item,month);
            java.util.List<java.util.Map.Entry<Long,
                java.util.List<PaycheckMonthlyBudget.Item>>> snapshot =
                new java.util.ArrayList<>(sums.entrySet());
            for (java.util.Map.Entry<Long,
                    java.util.List<PaycheckMonthlyBudget.Item>> state : snapshot) {
                long sum;
                try { sum = Math.addExact(state.getKey(),amount); }
                catch (ArithmeticException overflow) { continue; }
                if (sum > maxSum) continue;
                java.util.List<PaycheckMonthlyBudget.Item> next =
                    new java.util.ArrayList<>(state.getValue());
                next.add(item);
                java.util.List<PaycheckMonthlyBudget.Item> previous = sums.get(sum);
                if (previous == null) {
                    sums.put(sum,next);
                } else if (!sameBudgetItemSet(previous,next)) {
                    ambiguous.add(sum);
                }
            }
            if (sums.size() > 100000) {
                DiagnosticLog.event("PAYCHECK_BUDGET_SPLIT_STATE_LIMIT",
                    "states="+sums.size());
                break;
            }
        }

        java.util.List<PaycheckMonthlyBudget.Item> best = null;
        long bestDiff = Long.MAX_VALUE;
        boolean tied = false;
        for (java.util.Map.Entry<Long,
                java.util.List<PaycheckMonthlyBudget.Item>> state : sums.entrySet()) {
            if (state.getValue().size() < 2) continue;
            long diff = Math.abs(state.getKey()-transactionAmount);
            if (diff > tolerance) continue;
            if (diff < bestDiff) {
                bestDiff = diff;
                best = state.getValue();
                tied = ambiguous.contains(state.getKey());
            } else if (diff == bestDiff
                    && !sameBudgetItemSet(best,state.getValue())) {
                tied = true;
            }
        }
        return best == null || tied ? null
            : new java.util.ArrayList<>(best);
    }

    private boolean sameBudgetItemSet(
            java.util.List<PaycheckMonthlyBudget.Item> first,
            java.util.List<PaycheckMonthlyBudget.Item> second) {
        if (first == null || second == null || first.size()!=second.size())
            return false;
        java.util.HashSet<String> ids = new java.util.HashSet<>();
        for (PaycheckMonthlyBudget.Item item:first) ids.add(item.id);
        for (PaycheckMonthlyBudget.Item item:second)
            if (!ids.remove(item.id)) return false;
        return ids.isEmpty();
    }

    private void allocateBudgetSplit(
            java.util.List<PaycheckMonthlyBudget.Item> split,
            YearMonth month, String operationId, long transactionAmount)
            throws Exception {
        if (split == null || split.size() < 2 || transactionAmount < split.size())
            throw new IllegalArgumentException("Nie można podzielić tej kwoty.");
        long plannedTotal = 0L;
        for (PaycheckMonthlyBudget.Item item:split)
            plannedTotal = Math.addExact(plannedTotal,
                PaycheckMonthlyBudget.plannedAmount(item,month));
        if (plannedTotal <= 0L)
            throw new IllegalArgumentException("Nie można podzielić tej kwoty.");

        java.util.List<PaycheckMonthlyBudget.Item> ordered =
            new java.util.ArrayList<>(split);
        ordered.sort((a,b)->Long.compare(
            PaycheckMonthlyBudget.plannedAmount(a,month),
            PaycheckMonthlyBudget.plannedAmount(b,month)));

        long remaining = transactionAmount;
        for (int i=0;i<ordered.size();i++) {
            PaycheckMonthlyBudget.Item item=ordered.get(i);
            int left=ordered.size()-i-1;
            long allocation;
            if (i==ordered.size()-1) {
                allocation=remaining;
            } else if (transactionAmount==plannedTotal) {
                allocation=PaycheckMonthlyBudget.plannedAmount(item,month);
            } else {
                long planned=PaycheckMonthlyBudget.plannedAmount(item,month);
                allocation=Math.max(1L,
                    (planned*transactionAmount)/plannedTotal);
                allocation=Math.min(allocation,remaining-left);
            }
            if (allocation < 1L)
                throw new IllegalArgumentException("Nie można podzielić tej kwoty.");
            PaycheckMonthlyBudget.allocateMatch(
                prefs,item.id,operationId,allocation);
            remaining-=allocation;
        }
        if (remaining!=0L)
            throw new IllegalStateException("Nie rozdzielono całej transakcji.");
    }

    private boolean offerPrivateBudgetMatch(String operationId,
            Runnable done) {
        if(privatePaycheckSession==null
                || !privatePaycheckSession.active())return false;
        try {
            PrivatePaycheckVault.Entry tx=null;
            java.util.List<PrivatePaycheckVault.Entry> entries=
                PrivatePaycheckVault.entries(this,privatePaycheckSession);
            for(PrivatePaycheckVault.Entry entry:entries)
                if(operationId.equals(entry.operationId)) {
                    tx=entry;break;
                }
            if(tx==null || !"confirmed".equals(tx.status))return false;
            YearMonth month=YearMonth.from(
                Instant.ofEpochMilli(tx.createdAt)
                    .atZone(ZoneId.systemDefault()).toLocalDate());
            java.util.List<PaycheckMonthlyBudget.Item> items=
                PrivatePaycheckVault.budgetItems(
                    this,privatePaycheckSession);
            PaycheckMonthlyBudget.Item candidate=
                PaycheckMonthlyBudget.suggest(items,month,
                    tx.kind,tx.category,tx.amountGrosz);
            if(candidate==null)return false;
            final PrivatePaycheckVault.Entry chosenTx=tx;
            new AlertDialog.Builder(this)
                .setTitle("Pasuje do prywatnego budżetu")
                .setMessage(MoneyRules.format(chosenTx.amountGrosz)
                    +" wygląda jak „"+candidate.name+"”.\n\n"
                    +"Plan: "+MoneyRules.format(candidate.amountGrosz)
                    +" • "+budgetMonthLabel(month)
                    +"\n\nPrzypisać tę potwierdzoną transakcję?")
                .setNegativeButton("Nie, zostaw poza planem",(d,w)->done.run())
                .setPositiveButton("Tak, przypisz",(d,w)->{
                    try {
                        PrivatePaycheckVault.matchBudgetOperation(
                            this,privatePaycheckSession,
                            candidate.id,operationId);
                        DiagnosticLog.event(
                            "PAYCHECK_PRIVATE_BUDGET_MATCHED");
                    } catch(Exception error) {
                        alert("Transakcja została potwierdzona, ale nie "
                            +"przypisano jej do prywatnego budżetu.");
                    }
                    done.run();
                }).show();
            return true;
        } catch(Exception error) {
            return false;
        }
    }

    private void deleteSharedPaycheckEntriesBulk() {
        java.util.List<String> ids=new java.util.ArrayList<>();
        java.util.List<String> labels=new java.util.ArrayList<>();
        try(Cursor c=db.getReadableDatabase().rawQuery(
                "SELECT operation_id,kind,category,amount_grosz,note,status "
                +"FROM paycheck_transactions WHERE scope='shared' "
                +"ORDER BY id DESC LIMIT 200",null)) {
            while(c.moveToNext()) {
                ids.add(c.getString(0));
                labels.add(("income".equals(c.getString(1))?"+ ":"− ")
                    +MoneyRules.format(c.getLong(3))+" • "
                    +MoneyRules.categoryLabel(c.getString(2))
                    +(c.getString(4).isEmpty()?"":" • "+c.getString(4))
                    +("pending".equals(c.getString(5))
                        ?" • DO POTWIERDZENIA":""));
            }
        }
        if(ids.isEmpty()) {
            alert("Brak wpisów PayCheck do usunięcia.");
            return;
        }

        boolean[] checked=new boolean[ids.size()];
        new AlertDialog.Builder(this)
            .setTitle("Usuń wiele wpisów PayCheck")
            .setMultiChoiceItems(labels.toArray(new String[0]),checked,
                (dialog,which,isChecked)->checked[which]=isChecked)
            .setNegativeButton("Anuluj",null)
            .setNeutralButton("Wszystkie",(dialog,which)->{
                java.util.Arrays.fill(checked,true);
                confirmBulkPaycheckDelete(ids,checked);
            })
            .setPositiveButton("Dalej",(dialog,which)->
                confirmBulkPaycheckDelete(ids,checked))
            .show();
    }

    private void confirmBulkPaycheckDelete(
            java.util.List<String> ids, boolean[] checked) {
        java.util.List<String> selected=new java.util.ArrayList<>();
        for(int i=0;i<checked.length && i<ids.size();i++)
            if(checked[i])selected.add(ids.get(i));
        if(selected.isEmpty()) {
            alert("Nie zaznaczono żadnego wpisu.");
            return;
        }
        new AlertDialog.Builder(this)
            .setTitle("Usunąć zaznaczone?")
            .setMessage("Wpisów: "+selected.size()
                +"\nPotwierdzone pozycje zmienią saldo. "
                +"Dowody bankowe wrócą do kolejki „do sprawdzenia”.")
            .setNegativeButton("Anuluj",null)
            .setPositiveButton("Usuń zaznaczone",(dialog,which)->{
                try {
                    int removed=PaycheckStore.deleteMany(
                        db.getWritableDatabase(),selected);
                    for(String operationId:selected)
                        PaycheckMonthlyBudget.unmatch(prefs,operationId);
                    DiagnosticLog.event("PAYCHECK_SHARED_BULK_DELETED");
                    render();
                    alert("Usunięto wpisów PayCheck: "+removed+".");
                } catch(Exception error) {
                    DiagnosticLog.error("PAYCHECK_BULK_DELETE",error);
                    alert("Nie udało się usunąć zaznaczonych wpisów.");
                }
            }).show();
    }

    private void deleteSharedPaycheckEntry(String operationId) {
        new AlertDialog.Builder(this)
            .setTitle("Usunąć wpis PayCheck?")
            .setMessage("Usunięcie potwierdzonego wpisu przeliczy saldo. "
                +"Jeżeli wpis był uzgodniony z wyciągiem, dowód bankowy wróci "
                +"do kolejki „do sprawdzenia”. Powiązany koszt pojazdu pozostanie "
                +"w historii pojazdu jako koszt poza PayCheck.")
            .setNegativeButton("Anuluj",null)
            .setPositiveButton("Usuń",(dialog,which)->{
                try {
                    String result=PaycheckStore.delete(
                        db.getWritableDatabase(),operationId);
                    if("DELETED".equals(result)) {
                        PaycheckMonthlyBudget.unmatch(prefs,operationId);
                        DiagnosticLog.event("PAYCHECK_SHARED_DELETED");
                        render();
                    } else alert("Wpis już nie istnieje.");
                } catch(Exception error) {
                    DiagnosticLog.error("PAYCHECK_DELETE",error);
                    alert("Nie udało się usunąć wpisu. Dane bez zmian.");
                }
            }).show();
    }

    private void openPrivatePaycheck() {
        if (privatePaycheckSession != null && privatePaycheckSession.active()) {
            go("paycheck_private");
            return;
        }
        final boolean first = !PrivatePaycheckVault.configured(this);
        if (!first && PrivatePaycheckVault.cooldownMillis(this) > 0) {
            alert("Sejf czasowo zablokowany po błędnych hasłach. "
                + "Spróbuj za kilka minut.");
            return;
        }
        LinearLayout form = new LinearLayout(this);
        form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(18), dp(14), dp(18), dp(14));
        form.addView(text(first
            ? "Utwórz osobne hasło sejfu: 5–64 znaki. "
                + "Nie jest to PIN aplikacji. Bez hasła nie odzyskasz danych. "
                + "Sejf nie wchodzi do zwykłej kopii JSON. "
                + "Krótkie hasło (5 znaków) słabiej chroni dane; "
                + "zalecane jest dłuższe hasło."
            : "Wpisz hasło prywatnego sejfu. "
                + "Wspólny PayCheck pozostaje bez zmian.", 14, false));
        EditText password = new EditText(this);
        password.setSingleLine(true);
        password.setHint("Hasło prywatnego sejfu");
        password.setInputType(android.text.InputType.TYPE_CLASS_TEXT
            | android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);
        if (Build.VERSION.SDK_INT >= 26) {
            password.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);
            password.setImeOptions(
                android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);
        }
        form.addView(password);
        EditText confirmation = null;
        if (first) {
            confirmation = new EditText(this);
            confirmation.setSingleLine(true);
            confirmation.setHint("Powtórz hasło");
            confirmation.setInputType(android.text.InputType.TYPE_CLASS_TEXT
                | android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);
            if (Build.VERSION.SDK_INT >= 26) {
                confirmation.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);
                confirmation.setImeOptions(
                    android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);
            }
            form.addView(confirmation);
        }
        final EditText again = confirmation;
        lightDialogForm(form);
        AlertDialog dialog = new AlertDialog.Builder(this)
            .setTitle(first ? "Utwórz prywatny sejf" : "Otwórz prywatny sejf")
            .setView(form)
            .setNegativeButton("Anuluj", null)
            .setPositiveButton(first ? "Utwórz" : "Otwórz", null)
            .create();
        privateAuthDialog = dialog;
        dialog.setOnDismissListener(d -> {
            if (privateAuthDialog == dialog) privateAuthDialog = null;
            if (!"paycheck_private".equals(screen))
                getWindow().clearFlags(
                    android.view.WindowManager.LayoutParams.FLAG_SECURE);
        });
        dialog.setOnShowListener(d ->
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v -> {
                char[] secret = password.getText().toString().toCharArray();
                char[] confirm = again == null ? null
                    : again.getText().toString().toCharArray();
                try {
                    if (first && (!PrivatePaycheckCrypto.validPassword(secret)
                            || !java.util.Arrays.equals(secret, confirm))) {
                        password.setError("Hasła muszą być identyczne "
                            + "i mieć 5–64 znaki.");
                        return;
                    }
                    if (!first && PrivatePaycheckVault.cooldownMillis(this) > 0) {
                        password.setError("Poczekaj kilka minut.");
                        return;
                    }
                    PrivatePaycheckVault.Session session = first
                        ? PrivatePaycheckVault.configure(this, secret)
                        : PrivatePaycheckVault.unlock(this, secret);
                    PrivatePaycheckVault.clearFailures(this);
                    privatePaycheckSession = session;
                    password.getText().clear();
                    if (again != null) again.getText().clear();
                    dialog.dismiss();
                    go("paycheck_private");
                } catch (Exception denied) {
                    if (!first) PrivatePaycheckVault.recordFailure(this);
                    password.setError(first
                        ? "Nie utworzono sejfu. Spróbuj ponownie."
                        : "Nieprawidłowe hasło lub uszkodzony sejf.");
                } finally {
                    java.util.Arrays.fill(secret, '\0');
                    if (confirm != null) java.util.Arrays.fill(confirm, '\0');
                }
            }));
        getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);
        dialog.show();
        if (dialog.getWindow() != null)
            dialog.getWindow().addFlags(
                android.view.WindowManager.LayoutParams.FLAG_SECURE);
    }

    private String budgetMonthLabel(YearMonth month) {
        String name = month.getMonth().getDisplayName(
            TextStyle.FULL_STANDALONE, new Locale("pl", "PL"));
        if (!name.isEmpty())
            name = Character.toUpperCase(name.charAt(0)) + name.substring(1);
        return name + " " + month.getYear();
    }

    private void sharedMonthlyBudgetEntry() {
        final YearMonth month = YearMonth.now();
        try {
            java.util.List<PaycheckMonthlyBudget.Item> items =
                PaycheckMonthlyBudget.load(prefs);
            PaycheckMonthlyBudget.Totals plan =
                PaycheckMonthlyBudget.planned(items, month);
            title("Budżet miesiąca • " + budgetMonthLabel(month));
            note("Plan: wpływy " + MoneyRules.format(plan.income)
                + " • wydatki " + MoneyRules.format(plan.expense)
                + " • zostaje " + MoneyRules.format(plan.net()) + ".");
            button("📅 Wejdź do budżetu miesiąca • " + items.size()
                + (items.size()==1 ? " pozycja" : " pozycji"),
                () -> go("paycheck_budget"));
        } catch (Exception error) {
            DiagnosticLog.error("PAYCHECK_MONTHLY_BUDGET_ENTRY", error);
            button("📅 Wejdź do budżetu miesiąca",
                () -> go("paycheck_budget"));
        }
    }

    private void paycheckMonthlyBudget() {
        header("PayCheck • Budżet miesiąca");
        sharedMonthlyBudgetBlock();
    }

    private void sharedMonthlyBudgetBlock() {
        final YearMonth month = paycheckBudgetMonth == null
            ? YearMonth.now() : paycheckBudgetMonth;
        try {
            java.util.List<PaycheckMonthlyBudget.Item> items =
                PaycheckMonthlyBudget.load(prefs);
            PaycheckMonthlyBudget.Totals plan =
                PaycheckMonthlyBudget.planned(items, month);
            PaycheckMonthlyBudget.Totals confirmed =
                PaycheckMonthlyBudget.sharedActual(
                    db.getReadableDatabase(), month, "confirmed");
            PaycheckMonthlyBudget.Totals pending =
                PaycheckMonthlyBudget.sharedActual(
                    db.getReadableDatabase(), month, "pending");

            LinearLayout monthNav = new LinearLayout(this);
            monthNav.setOrientation(LinearLayout.HORIZONTAL);
            TextView previousMonth = budgetInlineButton("‹", () -> {
                paycheckBudgetMonth = month.minusMonths(1);
                expandedBudgetItemId = null;
                expandedBudgetDetailsView = null;
                render();
            });
            TextView monthLabel = text(budgetMonthLabel(month),18,true);
            monthLabel.setGravity(Gravity.CENTER);
            monthLabel.setTextColor(ink);
            if (!month.equals(YearMonth.now())) {
                monthLabel.setOnClickListener(v -> {
                    paycheckBudgetMonth = YearMonth.now();
                    expandedBudgetItemId = null;
                    expandedBudgetDetailsView = null;
                    render();
                });
                touchFeedback(monthLabel);
            }
            TextView nextMonth = budgetInlineButton("›", () -> {
                paycheckBudgetMonth = month.plusMonths(1);
                expandedBudgetItemId = null;
                expandedBudgetDetailsView = null;
                render();
            });
            monthNav.addView(previousMonth,new LinearLayout.LayoutParams(dp(52),dp(44)));
            monthNav.addView(monthLabel,new LinearLayout.LayoutParams(0,dp(44),1f));
            monthNav.addView(nextMonth,new LinearLayout.LayoutParams(dp(52),dp(44)));
            body.addView(monthNav,new LinearLayout.LayoutParams(-1,-2));

            note("Plan: wpływy " + MoneyRules.format(plan.income)
                + " • wydatki " + MoneyRules.format(plan.expense)
                + " • planowane saldo " + MoneyRules.format(plan.net()) + ".");
            note("Faktycznie potwierdzone: wpływy "
                + MoneyRules.format(confirmed.income) + " • wydatki "
                + MoneyRules.format(confirmed.expense)
                + " • saldo " + MoneyRules.format(confirmed.net()) + ".");
            long planVsActual = confirmed.net() - plan.net();
            note("Różnica plan–fakt: "
                + (planVsActual > 0 ? "+" : "")
                + MoneyRules.format(planVsActual) + ".");
            if (!pending.empty())
                note("Do potwierdzenia: wpływy "
                    + MoneyRules.format(pending.income) + " • wydatki "
                    + MoneyRules.format(pending.expense)
                    + ". Nie zmieniają salda ani wykonania budżetu.");
            long arrears = 0L;
            long credit = 0L;
            for (PaycheckMonthlyBudget.Item item : items) {
                long carry = PaycheckMonthlyBudget.sharedCarryBefore(
                    db.getReadableDatabase(),item,month);
                long availableCredit = PaycheckMonthlyBudget.sharedCreditBefore(
                    db.getReadableDatabase(),item,month);
                if (carry > 0) arrears = Math.addExact(arrears,carry);
                if (availableCredit > 0)
                    credit = Math.addExact(credit,availableCredit);
            }
            if (arrears > 0 || credit > 0)
                note("Z poprzednich miesięcy: zaległości "
                    + MoneyRules.format(arrears) + " • nadpłaty "
                    + MoneyRules.format(credit) + ".");
            note("Pozycja planowana nie jest transakcją. Saldo zmieniają dopiero "
                + "transakcje potwierdzone po sprawdzeniu banku / wyciągu.");

            button("＋ Dodaj pozycję", () -> showBudgetItemDialog(false));
            button("👥 Odbiorcy / szablony", this::showBudgetRecipientsDialog);

            java.util.List<PaycheckMonthlyBudget.Item> activeItems =
                PaycheckMonthlyBudget.activeFor(items, month);
            activeItems.sort((a,b) -> {
                int ad = budgetSortDay(a,month);
                int bd = budgetSortDay(b,month);
                int byDay = Integer.compare(ad,bd);
                return byDay != 0 ? byDay
                    : budgetItemDisplayName(a)
                        .compareToIgnoreCase(budgetItemDisplayName(b));
            });

            expandedBudgetDetailsView = null;

            int incomeCount = 0;
            for (PaycheckMonthlyBudget.Item item : activeItems)
                if ("income".equals(item.kind)) incomeCount++;
            title("Wpływy • " + incomeCount);
            if (incomeCount == 0) {
                note("Brak wpływów zaplanowanych na ten miesiąc.");
            } else {
                for (PaycheckMonthlyBudget.Item item : activeItems)
                    if ("income".equals(item.kind))
                        budgetItemCard(item, month);
            }

            java.util.List<PaycheckMonthlyBudget.Item> arrearItems =
                new java.util.ArrayList<>();
            java.util.List<PaycheckMonthlyBudget.Arrear> arrearRows =
                new java.util.ArrayList<>();
            for (PaycheckMonthlyBudget.Item item : items) {
                for (PaycheckMonthlyBudget.Arrear arrear
                        : PaycheckMonthlyBudget.sharedArrearsBefore(
                            db.getReadableDatabase(),item,month)) {
                    arrearItems.add(item);
                    arrearRows.add(arrear);
                }
            }
            java.util.List<Integer> arrearOrder = new java.util.ArrayList<>();
            for (int i=0;i<arrearRows.size();i++) arrearOrder.add(i);
            arrearOrder.sort((left,right) -> {
                PaycheckMonthlyBudget.Arrear a = arrearRows.get(left);
                PaycheckMonthlyBudget.Arrear b = arrearRows.get(right);
                int byMonth = a.sourceMonth.compareTo(b.sourceMonth);
                if (byMonth != 0) return byMonth;
                PaycheckMonthlyBudget.Item ai = arrearItems.get(left);
                PaycheckMonthlyBudget.Item bi = arrearItems.get(right);
                int ad = budgetSortDay(ai,a.sourceMonth);
                int bd = budgetSortDay(bi,b.sourceMonth);
                return Integer.compare(ad,bd);
            });

            int currentExpenseCount = 0;
            for (PaycheckMonthlyBudget.Item item : activeItems)
                if ("expense".equals(item.kind)) currentExpenseCount++;
            int expenseCount = arrearRows.size() + currentExpenseCount;
            title("Wydatki • " + expenseCount);
            if (expenseCount == 0) {
                note("Brak wydatków zaplanowanych na ten miesiąc.");
            } else {
                for (int index : arrearOrder)
                    budgetArrearRow(
                        arrearItems.get(index),arrearRows.get(index),month);
                for (PaycheckMonthlyBudget.Item item : activeItems)
                    if ("expense".equals(item.kind))
                        budgetItemCard(item, month);
            }

            button("📋 Wszystkie pozycje planu • " + items.size(),
                () -> showBudgetItemsDialog(false));
        } catch (Exception error) {
            DiagnosticLog.error("PAYCHECK_MONTHLY_BUDGET_READ", error);
            note("Nie udało się odczytać Budżetu miesiąca.");
        }
    }

    private int budgetSortDay(PaycheckMonthlyBudget.Item item,
            YearMonth month) {
        java.time.LocalDate planned =
            PaycheckMonthlyBudget.plannedPaymentDate(item,month);
        if (planned != null) return planned.getDayOfMonth();
        return item.dueDay <= 0 ? 99 : item.dueDay;
    }

    private String budgetItemDisplayName(PaycheckMonthlyBudget.Item item) {
        if (item == null) return "";
        if (item.recipientId == null || item.recipientId.isBlank())
            return item.name;
        try {
            String recipient = PaycheckRecipientStore.name(
                PaycheckRecipientStore.load(prefs),item.recipientId);
            if (recipient.isBlank()
                    || recipient.equalsIgnoreCase(item.name))
                return item.name;
            return recipient + " • " + item.name;
        } catch(Exception ignored) {
            return item.name;
        }
    }

    private String budgetDateLabel(java.time.LocalDate date) {
        if (date == null) return "—";
        return String.format(java.util.Locale.ROOT,"%02d.%02d",
            date.getDayOfMonth(),date.getMonthValue());
    }

    private void budgetItemCard(PaycheckMonthlyBudget.Item item,
            YearMonth month) {
        boolean scheduledThisMonth = !PaycheckMonthlyBudget.activeFor(
            java.util.Collections.singletonList(item),month).isEmpty();
        long planned = scheduledThisMonth
            ? PaycheckMonthlyBudget.plannedAmount(item, month) : 0L;
        long actual = PaycheckMonthlyBudget.sharedMatchedActual(
            db.getReadableDatabase(), item, month);
        long appliedCredit = PaycheckMonthlyBudget.creditAppliedTo(item,month);
        long availableCredit = PaycheckMonthlyBudget.sharedCreditBefore(
            db.getReadableDatabase(),item,month);
        long dueTotal = Math.max(0L,planned-appliedCredit);
        long balanceAfter = dueTotal-actual;

        java.time.LocalDate plannedDate =
            PaycheckMonthlyBudget.plannedPaymentDate(item,month);
        java.time.LocalDate invoiceDate =
            PaycheckMonthlyBudget.invoiceDueDate(item,month);
        String due = budgetDateLabel(plannedDate);
        String type;
        if (item.installment) {
            int position = PaycheckMonthlyBudget.installmentPosition(item, month);
            int total = PaycheckMonthlyBudget.installmentTotal(item);
            int includingCurrent = total > 0
                ? Math.max(0,total-position+1) : 0;
            String tail = includingCurrent == 1
                ? " • ⚠ ostatnia"
                : (includingCurrent == 2 ? " • ⚠ ostatnie 2" : "");
            type = total > 0
                ? "Rata " + position + "/" + total + tail
                : "Rata";
        } else if (item.cycleMonths == 0) {
            type = "1×";
        } else {
            type = "↻";
        }

        final String status;
        final int statusColor;
        if (!"expense".equals(item.kind)) {
            if (actual >= planned && planned > 0) {
                status = "POTWIERDZONE";
                statusColor = android.graphics.Color.rgb(56,142,60);
            } else if (actual > 0) {
                status = "CZĘŚCIOWO";
                statusColor = android.graphics.Color.rgb(251,192,45);
            } else {
                status = "OCZEKUJE";
                statusColor = android.graphics.Color.rgb(229,57,53);
            }
        } else if (item.optional && actual == 0) {
            status = "OPCJONALNE";
            statusColor = android.graphics.Color.rgb(30,136,229);
        } else if (balanceAfter < 0) {
            status = "NADPŁATA " + MoneyRules.format(-balanceAfter);
            statusColor = android.graphics.Color.rgb(251,192,45);
        } else if (balanceAfter == 0 && planned > 0) {
            status = "ZAPŁACONE";
            statusColor = android.graphics.Color.rgb(56,142,60);
        } else if (actual > 0) {
            status = "CZĘŚCIOWO • brakuje " + MoneyRules.format(balanceAfter);
            statusColor = android.graphics.Color.rgb(251,192,45);
        } else {
            status = "NIEZAPŁACONE";
            statusColor = android.graphics.Color.rgb(229,57,53);
        }

        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(0,dp(3),0,dp(3));
        LinearLayout.LayoutParams boxParams =
            new LinearLayout.LayoutParams(-1,-2);
        body.addView(box,boxParams);

        String prefix = due + "  " + budgetItemDisplayName(item) + "  "
            + MoneyRules.format(dueTotal) + "  [" + type + "]  ";
        android.text.SpannableString summary =
            new android.text.SpannableString(prefix + status);
        summary.setSpan(new android.text.style.StyleSpan(
                android.graphics.Typeface.BOLD),
            prefix.length(),summary.length(),
            android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);

        TextView line = text("",14,false);
        line.setText(summary);
        line.setSingleLine(true);
        line.setEllipsize(android.text.TextUtils.TruncateAt.END);
        line.setTextColor(statusColor);
        line.setPadding(dp(4),dp(7),dp(4),dp(7));
        box.addView(line,new LinearLayout.LayoutParams(-1,-2));

        LinearLayout details = new LinearLayout(this);
        details.setOrientation(LinearLayout.VERTICAL);
        boolean expanded = item.id.equals(expandedBudgetItemId);
        details.setVisibility(expanded ? View.VISIBLE : View.GONE);
        if (expanded) expandedBudgetDetailsView = details;

        if (item.recipientId != null && !item.recipientId.isBlank()) {
            try {
                String recipientName = PaycheckRecipientStore.name(
                    PaycheckRecipientStore.load(prefs),item.recipientId);
                if (!recipientName.isBlank())
                    details.addView(text("Odbiorca: " + recipientName,13,false));
            } catch(Exception ignored) { }
        }
        details.addView(text("Zobowiązanie: " + item.name,13,false));
        details.addView(text("Kategoria: "
            + MoneyRules.categoryLabel(item.category),13,false));
        if (item.creditAgreementNumber != null
                && !item.creditAgreementNumber.isBlank())
            details.addView(text("Nr umowy kredytowej: "
                + item.creditAgreementNumber,13,false));
        if (invoiceDate != null)
            details.addView(text("Termin faktury: " + invoiceDate
                + " • planowana zapłata: " + plannedDate,13,false));
        details.addView(text("Plan tego miesiąca: " + MoneyRules.format(planned)
            + " • zapłacono/potwierdzono: " + MoneyRules.format(actual),
            13,false));
        if ("expense".equals(item.kind) && appliedCredit > 0)
            details.addView(text("Odliczona nadpłata: "
                + MoneyRules.format(appliedCredit),13,false));
        if ("expense".equals(item.kind) && availableCredit > 0)
            details.addView(text("Dostępna nadpłata z wcześniejszych miesięcy: "
                + MoneyRules.format(availableCredit)
                + " • nie jest odliczana automatycznie.",13,false));
        if (item.optional)
            details.addView(text(
                "Opcjonalne • brak realizacji nie tworzy zaległości.",
                13,false));
        if (item.installment) {
            int position = PaycheckMonthlyBudget.installmentPosition(item,month);
            int total = PaycheckMonthlyBudget.installmentTotal(item);
            int left = total > 0 ? Math.max(0,total-position) : 0;
            long totalPlanned =
                PaycheckMonthlyBudget.installmentTotalPlanned(item);
            long totalPaid =
                PaycheckMonthlyBudget.sharedMatchedActualAll(
                    db.getReadableDatabase(),item);
            long totalLeft = Math.max(0L,totalPlanned-totalPaid);
            java.time.YearMonth end =
                PaycheckMonthlyBudget.installmentEndMonth(item);
            details.addView(text(total > 0
                ? "Rata " + position + "/" + total + " • zostało " + left
                    + " • koniec " + (end == null ? "—" : end)
                : "Rata",13,false));
            details.addView(text("Zobowiązanie łącznie: "
                + MoneyRules.format(totalPlanned)
                + " • zapłacono: " + MoneyRules.format(totalPaid)
                + " • pozostało: " + MoneyRules.format(totalLeft),
                13,false));
        }

        if (!"income".equals(item.kind)) {
            try {
                java.util.List<PaycheckBudgetAttachmentStore.Attachment> attachments =
                    PaycheckBudgetAttachmentStore.list(prefs,item.id);
                details.addView(text("Faktura / załącznik"
                    + (attachments.isEmpty() ? "" : " • " + attachments.size()),
                    13,true));
                for (PaycheckBudgetAttachmentStore.Attachment attachment:attachments)
                    details.addView(budgetInlineButton(
                        "📎 " + attachment.displayName,
                        () -> showBudgetAttachmentActions(item,attachment)),
                        new LinearLayout.LayoutParams(-1,dp(40)));
                details.addView(budgetInlineButton("＋ Dodaj zdjęcie / PDF",
                    () -> pickBudgetAttachment(item)),
                    new LinearLayout.LayoutParams(-1,dp(40)));
            } catch(Exception error) {
                DiagnosticLog.error("PAYCHECK_ATTACHMENT_LIST",error);
                details.addView(text(
                    "Nie udało się odczytać załączników.",12,false));
            }
        }

        details.addView(budgetInlineButton("Historia",
            () -> showBudgetItemHistory(item)),
            new LinearLayout.LayoutParams(-1,dp(40)));

        LinearLayout actions = new LinearLayout(this);
        actions.setOrientation(LinearLayout.HORIZONTAL);
        actions.addView(budgetInlineButton("Zmień kwotę",
            () -> showBudgetAmountChangeDialog(item,month)),
            new LinearLayout.LayoutParams(0,dp(40),1f));
        if (item.optional) {
            actions.addView(budgetInlineButton("Przenieś →",
                () -> moveBudgetOptional(item,month)),
                new LinearLayout.LayoutParams(0,dp(40),1f));
            actions.addView(budgetInlineButton("Zamknij",
                () -> closeBudgetOptional(item,month)),
                new LinearLayout.LayoutParams(0,dp(40),1f));
        } else if ("expense".equals(item.kind)
                && availableCredit > 0 && balanceAfter > 0) {
            actions.addView(budgetInlineButton("Odlicz nadpłatę",
                () -> showApplyBudgetCreditDialog(item,month)),
                new LinearLayout.LayoutParams(0,dp(40),1f));
        }
        details.addView(actions,new LinearLayout.LayoutParams(-1,-2));

        LinearLayout lifecycle = new LinearLayout(this);
        lifecycle.setOrientation(LinearLayout.HORIZONTAL);
        if (item.cycleMonths > 0)
            lifecycle.addView(budgetInlineButton("Zamknij / cykl",
                () -> endBudgetCycle(item,month)),
                new LinearLayout.LayoutParams(0,dp(40),1f));
        lifecycle.addView(budgetInlineButton("Usuń / korekta",
            () -> confirmBudgetItemDelete(false,item)),
            new LinearLayout.LayoutParams(0,dp(40),1f));
        details.addView(lifecycle,new LinearLayout.LayoutParams(-1,-2));

        box.addView(details,new LinearLayout.LayoutParams(-1,-2));
        View separator = new View(this);
        separator.setBackgroundColor(android.graphics.Color.argb(38,128,128,128));
        box.addView(separator,new LinearLayout.LayoutParams(-1,dp(1)));

        line.setOnClickListener(v -> {
            if (details.getVisibility() == View.VISIBLE) {
                details.setVisibility(View.GONE);
                if (item.id.equals(expandedBudgetItemId))
                    expandedBudgetItemId = null;
                if (expandedBudgetDetailsView == details)
                    expandedBudgetDetailsView = null;
                return;
            }
            if (expandedBudgetDetailsView != null
                    && expandedBudgetDetailsView != details)
                expandedBudgetDetailsView.setVisibility(View.GONE);
            expandedBudgetItemId = item.id;
            expandedBudgetDetailsView = details;
            details.setVisibility(View.VISIBLE);
        });
        touchFeedback(line);
    }

    private String budgetHistoryTypeLabel(String type) {
        if (type == null) return "Zdarzenie";
        switch (type) {
            case "ITEM_CREATED": return "Dodano do planu";
            case "ITEM_DEACTIVATED": return "Usunięto / zakończono";
            case "TRANSACTION_MATCHED": return "Powiązano transakcję";
            case "TRANSACTION_ALLOCATED": return "Przypisano część transakcji";
            case "TRANSACTION_UNMATCHED": return "Odłączono transakcję";
            case "OPTIONAL_MOVED": return "Przeniesiono na kolejny miesiąc";
            case "OPTIONAL_CLOSED": return "Zamknięto pozycję opcjonalną";
            case "AMOUNT_MONTH_CHANGED": return "Zmieniono kwotę tego miesiąca";
            case "AMOUNT_FROM_CHANGED": return "Zmieniono kwotę od tego miesiąca";
            case "CREDIT_APPLIED": return "Odliczono nadpłatę";
            case "ARREAR_CLOSED": return "Zamknięto zaległość";
            case "OCCURRENCE_CLOSED": return "Zamknięto wystąpienie";
            case "CYCLE_ENDED": return "Zakończono cykl";
            default: return type.replace('_',' ');
        }
    }

    private void showBudgetItemHistory(PaycheckMonthlyBudget.Item item) {
        try {
            java.util.List<PaycheckBudgetHistoryStore.Event> events =
                new java.util.ArrayList<>();
            for (PaycheckBudgetHistoryStore.Event event
                    : PaycheckBudgetHistoryStore.load(prefs))
                if (item.id.equals(event.itemId)) events.add(event);
            events.sort((left,right) ->
                Long.compare(right.createdAt,left.createdAt));
            if (events.isEmpty()) {
                alert("Brak historii tej pozycji.");
                return;
            }
            int count = Math.min(events.size(),100);
            String[] labels = new String[count];
            for (int i=0;i<count;i++) {
                PaycheckBudgetHistoryStore.Event event = events.get(i);
                String eventMonth = budgetMonthLabel(YearMonth.parse(event.month));
                String amount = event.amountGrosz == 0L ? ""
                    : " • " + MoneyRules.format(event.amountGrosz);
                String note = event.note == null ? "" : event.note.trim();
                boolean internalId = note.matches("[0-9a-fA-F-]{36}");
                String detail = note.isEmpty() || internalId ? ""
                    : "\n" + note;
                String date = Instant.ofEpochMilli(event.createdAt)
                    .atZone(ZoneId.systemDefault()).toLocalDate().toString();
                labels[i] = budgetHistoryTypeLabel(event.type) + " • "
                    + eventMonth + amount + detail + "\n" + date;
            }
            new AlertDialog.Builder(this)
                .setTitle("Historia • " + budgetItemDisplayName(item))
                .setItems(labels,null)
                .setNegativeButton("Zamknij",null)
                .show();
        } catch(Exception error) {
            DiagnosticLog.error("PAYCHECK_BUDGET_HISTORY_VIEW",error);
            alert("Nie udało się otworzyć historii tej pozycji.");
        }
    }

    private void pickBudgetAttachment(
            PaycheckMonthlyBudget.Item item) {
        pendingBudgetAttachmentItemId=item.id;
        Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT);
        picker.addCategory(Intent.CATEGORY_OPENABLE);
        picker.setType("*/*");
        picker.putExtra(Intent.EXTRA_MIME_TYPES,
            new String[]{"application/pdf","image/jpeg","image/png",
                "image/webp","image/*"});
        try {
            startActivityForResult(picker,IMPORT_PAYCHECK_ATTACHMENT);
        } catch(Exception error) {
            pendingBudgetAttachmentItemId=null;
            alert("Nie można otworzyć wyboru zdjęcia lub PDF.");
        }
    }

    private void showBudgetAttachmentActions(
            PaycheckMonthlyBudget.Item item,
            PaycheckBudgetAttachmentStore.Attachment attachment) {
        new AlertDialog.Builder(this)
            .setTitle(attachment.displayName)
            .setItems(new String[]{"Otwórz","Usuń załącznik"},(d,which)->{
                if (which==0) {
                    openBudgetAttachment(attachment);
                    return;
                }
                new AlertDialog.Builder(this)
                    .setTitle("Usunąć załącznik?")
                    .setMessage(attachment.displayName
                        + "\n\nPo usunięciu zniknie również z kolejnej "
                        + "pełnej kopii ZIP.")
                    .setNegativeButton("Anuluj",null)
                    .setPositiveButton("Usuń",(confirm,w)->{
                        try {
                            if (PaycheckBudgetAttachmentStore.remove(
                                    this,prefs,attachment.id)) {
                                PaycheckBudgetHistoryStore.append(
                                    prefs,item,
                                    paycheckBudgetMonth==null
                                        ?YearMonth.now():paycheckBudgetMonth,
                                    "ATTACHMENT_REMOVED",0L,
                                    attachment.displayName);
                                DiagnosticLog.event(
                                    "PAYCHECK_ATTACHMENT_REMOVED");
                                render();
                            }
                        } catch(Exception error) {
                            DiagnosticLog.error(
                                "PAYCHECK_ATTACHMENT_REMOVE",error);
                            alert("Nie udało się usunąć załącznika.");
                        }
                    })
                    .show();
            })
            .setNegativeButton("Zamknij",null)
            .show();
    }

    private void openBudgetAttachment(
            PaycheckBudgetAttachmentStore.Attachment attachment) {
        try {
            Uri uri=PaycheckBudgetAttachmentStore.uri(this,attachment);
            Intent open=new Intent(Intent.ACTION_VIEW);
            open.setDataAndType(uri,attachment.mime);
            open.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
            startActivity(open);
        } catch(Exception error) {
            DiagnosticLog.error("PAYCHECK_ATTACHMENT_OPEN",error);
            alert("Nie można otworzyć tego załącznika.");
        }
    }

    private void budgetArrearRow(PaycheckMonthlyBudget.Item item,
            PaycheckMonthlyBudget.Arrear arrear, YearMonth shownMonth) {
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(0,dp(3),0,dp(3));
        body.addView(box,new LinearLayout.LayoutParams(-1,-2));

        String monthLabel = arrear.sourceMonth.getMonth().getDisplayName(
            java.time.format.TextStyle.SHORT_STANDALONE,
            new java.util.Locale("pl","PL")).toUpperCase(
                new java.util.Locale("pl","PL"));
        String due = budgetDateLabel(
            PaycheckMonthlyBudget.plannedPaymentDate(
                item,arrear.sourceMonth));
        String prefix = due + "  Niedopłata "
            + budgetItemDisplayName(item) + " z "
            + monthLabel + " " + arrear.sourceMonth.getYear() + "  "
            + MoneyRules.format(arrear.amountGrosz) + "  ";
        String status = "ZALEGŁE";
        android.text.SpannableString summary =
            new android.text.SpannableString(prefix+status);
        int red = android.graphics.Color.rgb(229,57,53);
        summary.setSpan(new android.text.style.ForegroundColorSpan(red),
            prefix.length(),summary.length(),
            android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
        summary.setSpan(new android.text.style.StyleSpan(
                android.graphics.Typeface.BOLD),
            prefix.length(),summary.length(),
            android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);

        TextView line = text("",14,false);
        line.setText(summary);
        line.setSingleLine(true);
        line.setEllipsize(android.text.TextUtils.TruncateAt.END);
        line.setTextColor(ink);
        line.setPadding(dp(4),dp(7),dp(4),dp(7));
        box.addView(line,new LinearLayout.LayoutParams(-1,-2));

        String rowId = "arrear:" + item.id + ":" + arrear.sourceMonth;
        LinearLayout details = new LinearLayout(this);
        details.setOrientation(LinearLayout.VERTICAL);
        boolean expanded = rowId.equals(expandedBudgetItemId);
        details.setVisibility(expanded ? View.VISIBLE : View.GONE);
        if (expanded) expandedBudgetDetailsView = details;
        details.addView(text("Pozycja: " + item.name
            + " • miesiąc źródłowy: "
            + budgetMonthLabel(arrear.sourceMonth),13,false));
        details.addView(text("Pozostało do rozliczenia: "
            + MoneyRules.format(arrear.amountGrosz),13,false));
        details.addView(budgetInlineButton("Zamknij ręcznie z powodem",
            () -> showCloseBudgetArrearsDialog(
                item,arrear.sourceMonth,arrear.amountGrosz)),
            new LinearLayout.LayoutParams(-1,dp(40)));
        box.addView(details,new LinearLayout.LayoutParams(-1,-2));

        View separator = new View(this);
        separator.setBackgroundColor(android.graphics.Color.argb(38,128,128,128));
        box.addView(separator,new LinearLayout.LayoutParams(-1,dp(1)));

        line.setOnClickListener(v -> {
            if (details.getVisibility() == View.VISIBLE) {
                details.setVisibility(View.GONE);
                if (rowId.equals(expandedBudgetItemId))
                    expandedBudgetItemId = null;
                if (expandedBudgetDetailsView == details)
                    expandedBudgetDetailsView = null;
                return;
            }
            if (expandedBudgetDetailsView != null
                    && expandedBudgetDetailsView != details)
                expandedBudgetDetailsView.setVisibility(View.GONE);
            expandedBudgetItemId = rowId;
            expandedBudgetDetailsView = details;
            details.setVisibility(View.VISIBLE);
        });
        touchFeedback(line);
    }

    private void showApplyBudgetCreditDialog(
            PaycheckMonthlyBudget.Item item, YearMonth targetMonth) {
        java.util.List<PaycheckMonthlyBudget.Credit> credits =
            PaycheckMonthlyBudget.sharedCreditsBefore(
                db.getReadableDatabase(),item,targetMonth);
        if (credits.isEmpty()) {
            alert("Brak dostępnej nadpłaty do odliczenia.");
            return;
        }
        String[] labels = new String[credits.size()];
        for (int i=0;i<credits.size();i++) {
            PaycheckMonthlyBudget.Credit credit = credits.get(i);
            labels[i] = budgetMonthLabel(credit.sourceMonth)
                + " • " + MoneyRules.format(credit.amountGrosz);
        }
        new AlertDialog.Builder(this)
            .setTitle("Odliczyć nadpłatę?")
            .setMessage("Nadpłata nie jest używana automatycznie. "
                + "Wybierz, z którego miesiąca ją odliczyć.")
            .setItems(labels,(d,which) -> {
                PaycheckMonthlyBudget.Credit credit = credits.get(which);
                long planned = PaycheckMonthlyBudget.plannedAmount(
                    item,targetMonth);
                long applied = PaycheckMonthlyBudget.creditAppliedTo(
                    item,targetMonth);
                long amount = Math.min(credit.amountGrosz,
                    Math.max(0L,planned-applied));
                if (amount <= 0L) {
                    alert("Ta pozycja nie wymaga już odliczenia.");
                    return;
                }
                new AlertDialog.Builder(this)
                    .setTitle("Potwierdź odliczenie")
                    .setMessage("Odliczyć "
                        + MoneyRules.format(amount)
                        + " z nadpłaty " + budgetMonthLabel(credit.sourceMonth)
                        + " od pozycji „" + item.name + "” w "
                        + budgetMonthLabel(targetMonth) + "?")
                    .setNegativeButton("Anuluj",null)
                    .setPositiveButton("Odlicz",(confirm,w) -> {
                        try {
                            PaycheckMonthlyBudget.applyCredit(
                                prefs,db.getReadableDatabase(),item.id,
                                credit.sourceMonth,targetMonth,amount);
                            DiagnosticLog.event(
                                "PAYCHECK_BUDGET_CREDIT_APPLIED");
                            render();
                        } catch(Exception error) {
                            alert(error.getMessage()==null
                                ? "Nie odliczono nadpłaty."
                                : error.getMessage());
                        }
                    })
                    .show();
            })
            .setNegativeButton("Anuluj",null)
            .show();
    }

    private Button budgetInlineButton(String label, Runnable action) {
        Button button = new Button(this);
        button.setText(label);
        button.setAllCaps(false);
        button.setTextSize(12);
        button.setTextColor(skin.accentInk);
        button.setBackground(skin.pill(this, accent));
        button.setMinHeight(0);
        button.setMinimumHeight(0);
        button.setOnClickListener(v -> action.run());
        touchFeedback(button);
        return button;
    }

    private void showCloseBudgetArrearsDialog(
            PaycheckMonthlyBudget.Item item, YearMonth sourceMonth,
            long amountGrosz) {
        final String[] reasons = {
            "Anulowana faktura",
            "Rozliczone inaczej",
            "Błędnie dodane",
            "Umorzone",
            "Pokryte poza PayCheck",
            "Inne"
        };
        LinearLayout form = new LinearLayout(this);
        form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(18),dp(12),dp(18),dp(12));
        Spinner reasonType = new Spinner(this);
        reasonType.setAdapter(lightDialogSpinnerAdapter(
            java.util.Arrays.asList(reasons)));
        form.addView(reasonType);
        EditText detail = new EditText(this);
        detail.setSingleLine(false);
        detail.setHint("Dodatkowy opis (wymagany dla „Inne”)");
        detail.setFilters(new android.text.InputFilter[]{
            new android.text.InputFilter.LengthFilter(120)});
        form.addView(detail);
        reasonType.setPopupBackgroundDrawable(
            new android.graphics.drawable.ColorDrawable(
                DialogContrast.BACKGROUND));
        lightDialogForm(form);

        AlertDialog dialog = new AlertDialog.Builder(this)
            .setTitle("Zamknąć zaległość • "
                + MoneyRules.format(amountGrosz))
            .setMessage("Miesiąc źródłowy: "
                + budgetMonthLabel(sourceMonth)
                + "\nTransakcje PayCheck pozostaną bez zmian. "
                + "Data i powód zamknięcia zostaną zachowane w historii.")
            .setView(form)
            .setNegativeButton("Anuluj",null)
            .setPositiveButton("Zamknij",null)
            .create();
        dialog.setOnShowListener(d ->
            dialog.getButton(AlertDialog.BUTTON_POSITIVE)
                .setOnClickListener(v -> {
                    String base = reasons[reasonType.getSelectedItemPosition()];
                    String extra = detail.getText().toString().trim();
                    if ("Inne".equals(base) && extra.isEmpty()) {
                        detail.setError("Podaj powód zamknięcia.");
                        return;
                    }
                    String reason = "Inne".equals(base)
                        ? extra
                        : (extra.isEmpty() ? base : base + " • " + extra);
                    try {
                        PaycheckMonthlyBudget.closeArrears(
                            prefs,item.id,sourceMonth,amountGrosz,reason);
                        DiagnosticLog.event(
                            "PAYCHECK_BUDGET_ARREARS_CLOSED");
                        dialog.dismiss();
                        render();
                    } catch(Exception error) {
                        alert(error.getMessage()==null
                            ? "Nie zamknięto zaległości."
                            : error.getMessage());
                    }
                }));
        dialog.show();
    }

